   55      /// Establish a connection with the Redis server located at `addr`.
   56      ///
   57      /// `addr` may be any type that can be asynchronously converted to a
   58      /// `SocketAddr`. This includes `SocketAddr` and strings. The `ToSocketAddrs`
   59      /// trait is the Tokio version and not the `std` version.
   60      ///
   61      /// # Examples
   62      ///
   63      /// ```no_run
   64      /// use mini_redis::clients::Client;
   65      ///
   66      /// #[tokio::main]
   67      /// async fn main() {
   68      ///     let client = match Client::connect("localhost:6379").await {
   69      ///         Ok(client) => client,
   70      ///         Err(_) => panic!("failed to establish connection"),
   71      ///     };
   72      /// # drop(client);
   73      /// }
   74      /// ```
   75      ///
   76      pub async fn connect<T: ToSocketAddrs>(addr: T) -> crate::Result<Client> {
   77          // The `addr` argument is passed directly to `TcpStream::connect`. This
   78          // performs any asynchronous DNS lookup and attempts to establish the TCP
   79          // connection. An error at either step returns an error, which is then
   80          // bubbled up to the caller of `mini_redis` connect.
   81          let socket = TcpStream::connect(addr).await?;
   82  
   83          // Initialize the connection state. This allocates read/write buffers to
   84          // perform redis protocol frame parsing.
   85          let connection = Connection::new(socket);
   86  
   87          Ok(Client { connection })
   88      }
