   93      /// return a copy of the argument as a bulk.
   94      ///
   95      /// This command is often used to test if a connection
   96      /// is still alive, or to measure latency.
   97      ///
   98      /// # Examples
   99      ///
  100      /// Demonstrates basic usage.
  101      /// ```no_run
  102      /// use mini_redis::clients::Client;
  103      ///
  104      /// #[tokio::main]
  105      /// async fn main() {
  106      ///     let mut client = Client::connect("localhost:6379").await.unwrap();
  107      ///
  108      ///     let pong = client.ping(None).await.unwrap();
  109      ///     assert_eq!(b"PONG", &pong[..]);
