  112      #[instrument(skip(self))]
  113      pub async fn ping(&mut self, msg: Option<Bytes>) -> crate::Result<Bytes> {
  114          let frame = Ping::new(msg).into_frame();
  115          debug!(request = ?frame);
  116          self.connection.write_frame(&frame).await?;
  117  
  118          match self.read_response().await? {
  119              Frame::Simple(value) => Ok(value.into()),
  120              Frame::Bulk(value) => Ok(value),
  121              frame => Err(frame.to_error()),
  122          }
  123      }
