  157          // Both `Simple` and `Bulk` frames are accepted. `Null` represents the
  158          // key not being present and `None` is returned.
  159          match self.read_response().await? {
  160              Frame::Simple(value) => Ok(Some(value.into())),
  161              Frame::Bulk(value) => Ok(Some(value)),
  162              Frame::Null => Ok(None),
