  224      /// async fn main() {
  225      ///     let ttl = Duration::from_millis(500);
  226      ///     let mut client = Client::connect("localhost:6379").await.unwrap();
  227      ///
  228      ///     client.set_expires("foo", "bar".into(), ttl).await.unwrap();
  229      ///
  230      ///     // Getting the value immediately works
  231      ///     let val = client.get("foo").await.unwrap().unwrap();
