  254      /// The core `SET` logic, used by both `set` and `set_expires.
  255      async fn set_cmd(&mut self, cmd: Set) -> crate::Result<()> {
  256          // Convert the `Set` command into a frame
  257          let frame = cmd.into_frame();
  258  
  259          debug!(request = ?frame);
  260  
  261          // Write the frame to the socket. This writes the full frame to the
  262          // socket, waiting if necessary.
  263          self.connection.write_frame(&frame).await?;
  264  
  265          // Wait for the response from the server. On success, the server
  266          // responds simply with `OK`. Any other response indicates an error.
  267          match self.read_response().await? {
  268              Frame::Simple(response) if response == "OK" => Ok(()),
  269              frame => Err(frame.to_error()),
  270          }
  271      }
