  311      /// Subscribes the client to the specified channels.
  312      ///
  313      /// Once a client issues a subscribe command, it may no longer issue any
  314      /// non-pub/sub commands. The function consumes `self` and returns a `Subscriber`.
  315      ///
  316      /// The `Subscriber` value is used to receive messages as well as manage the
  317      /// list of channels the client is subscribed to.
  318      #[instrument(skip(self))]
  319      pub async fn subscribe(mut self, channels: Vec<String>) -> crate::Result<Subscriber> {
  320          // Issue the subscribe command to the server and wait for confirmation.
  321          // The client will then have been transitioned into the "subscriber"
  322          // state and may only issue pub/sub commands from that point on.
  323          self.subscribe_cmd(&channels).await?;
  324  
  325          // Return the `Subscriber` type
  326          Ok(Subscriber {
  327              client: self,
  328              subscribed_channels: channels,
  329          })
  330      }
