  332      /// The core `SUBSCRIBE` logic, used by misc subscribe fns
  333      async fn subscribe_cmd(&mut self, channels: &[String]) -> crate::Result<()> {
  334          // Convert the `Subscribe` command into a frame
  335          let frame = Subscribe::new(channels.to_vec()).into_frame();
  336  
  337          debug!(request = ?frame);
  338  
  339          // Write the frame to the socket
  340          self.connection.write_frame(&frame).await?;
  341  
  342          // For each channel being subscribed to, the server responds with a
  343          // message confirming subscription to that channel.
  344          for channel in channels {
  345              // Read the response
  346              let response = self.read_response().await?;
  347  
  348              // Verify it is confirmation of subscription.
  349              match response {
  350                  Frame::Array(ref frame) => match frame.as_slice() {
  351                      // The server responds with an array frame in the form of:
  352                      //
  353                      // ```
  354                      // [ "subscribe", channel, num-subscribed ]
  355                      // ```
  356                      //
  357                      // where channel is the name of the channel and
  358                      // num-subscribed is the number of channels that the client
  359                      // is currently subscribed to.
  360                      [subscribe, schannel, ..]
  361                          if *subscribe == "subscribe" && *schannel == channel => {}
  362                      _ => return Err(response.to_error()),
  363                  },
  364                  frame => return Err(frame.to_error()),
  365              };
  366          }
  367  
  368          Ok(())
  369      }
