  371      /// Reads a response frame from the socket.
  372      ///
  373      /// If an `Error` frame is received, it is converted to `Err`.
  374      async fn read_response(&mut self) -> crate::Result<Frame> {
  375          let response = self.connection.read_frame().await?;
  376  
  377          debug!(?response);
  378  
  379          match response {
  380              // Error frames are converted to `Err`
  381              Some(Frame::Error(msg)) => Err(msg.into()),
  382              Some(frame) => Ok(frame),
  383              None => {
  384                  // Receiving `None` here indicates the server has closed the
  385                  // connection without sending a frame. This is unexpected and is
  386                  // represented as a "connection reset by peer" error.
  387                  let err = Error::new(ErrorKind::ConnectionReset, "connection reset by server");
  388  
  389                  Err(err.into())
  390              }
  391          }
  392      }
  393  }
