  395  impl Subscriber {
  396      /// Returns the set of channels currently subscribed to.
  397      pub fn get_subscribed(&self) -> &[String] {
  398          &self.subscribed_channels
  399      }
  400  
  401      /// Receive the next message published on a subscribed channel, waiting if
  402      /// necessary.
  403      ///
  404      /// `None` indicates the subscription has been terminated.
  405      pub async fn next_message(&mut self) -> crate::Result<Option<Message>> {
  406          match self.client.connection.read_frame().await? {
  407              Some(mframe) => {
  408                  debug!(?mframe);
  409  
  410                  match mframe {
  411                      Frame::Array(ref frame) => match frame.as_slice() {
  412                          [message, channel, content] if *message == "message" => Ok(Some(Message {
  413                              channel: channel.to_string(),
  414                              content: Bytes::from(content.to_string()),
  415                          })),
  416                          _ => Err(mframe.to_error()),
  417                      },
  418                      frame => Err(frame.to_error()),
  419                  }
  420              }
  421              None => Ok(None),
  422          }
  423      }
  424  
  425      /// Convert the subscriber into a `Stream` yielding new messages published
  426      /// on subscribed channels.
  427      ///
  428      /// `Subscriber` does not implement stream itself as doing so with safe code
  429      /// is non trivial. The usage of async/await would require a manual Stream
  430      /// implementation to use `unsafe` code. Instead, a conversion function is
  431      /// provided and the returned stream is implemented with the help of the
  432      /// `async-stream` crate.
  433      pub fn into_stream(mut self) -> impl Stream<Item = crate::Result<Message>> {
  434          // Uses the `try_stream` macro from the `async-stream` crate. Generators
  435          // are not stable in Rust. The crate uses a macro to simulate generators
  436          // on top of async/await. There are limitations, so read the
  437          // documentation there.
  438          try_stream! {
  439              while let Some(message) = self.next_message().await? {
  440                  yield message;
  441              }
  442          }
  443      }
