  445      /// Subscribe to a list of new channels
  446      #[instrument(skip(self))]
  447      pub async fn subscribe(&mut self, channels: &[String]) -> crate::Result<()> {
  448          // Issue the subscribe command
  449          self.client.subscribe_cmd(channels).await?;
  450  
  451          // Update the set of subscribed channels.
  452          self.subscribed_channels
  453              .extend(channels.iter().map(Clone::clone));
  454  
  455          Ok(())
  456      }
  457  
  458      /// Unsubscribe to a list of new channels
  459      #[instrument(skip(self))]
  460      pub async fn unsubscribe(&mut self, channels: &[String]) -> crate::Result<()> {
  461          let frame = Unsubscribe::new(channels).into_frame();
  462  
  463          debug!(request = ?frame);
  464  
  465          // Write the frame to the socket
  466          self.client.connection.write_frame(&frame).await?;
  467  
  468          // if the input channel list is empty, server acknowledges as unsubscribing
  469          // from all subscribed channels, so we assert that the unsubscribe list received
  470          // matches the client subscribed one
  471          let num = if channels.is_empty() {
  472              self.subscribed_channels.len()
  473          } else {
  474              channels.len()
  475          };
  476  
  477          // Read the response
  478          for _ in 0..num {
  479              let response = self.client.read_response().await?;
  480  
  481              match response {
  482                  Frame::Array(ref frame) => match frame.as_slice() {
  483                      [unsubscribe, channel, ..] if *unsubscribe == "unsubscribe" => {
  484                          let len = self.subscribed_channels.len();
  485  
  486                          if len == 0 {
  487                              // There must be at least one channel
  488                              return Err(response.to_error());
  489                          }
  490  
  491                          // unsubscribed channel should exist in the subscribed list at this point
  492                          self.subscribed_channels.retain(|c| *channel != &c[..]);
  493  
  494                          // Only a single channel should be removed from the
  495                          // list of subscribed channels.
  496                          if self.subscribed_channels.len() != len - 1 {
  497                              return Err(response.to_error());
  498                          }
  499                      }
  500                      _ => return Err(response.to_error()),
  501                  },
  502                  frame => return Err(frame.to_error()),
  503              };
  504          }
  505  
  506          Ok(())
  507      }
  508  }
