    1  use crate::clients::Client;
    2  use crate::Result;
    3  
    4  use bytes::Bytes;
    5  use tokio::sync::mpsc::{channel, Receiver, Sender};
    6  use tokio::sync::oneshot;
    7  
    8  // Enum used to message pass the requested command from the `BufferedClient` handle
    9  #[derive(Debug)]
   10  enum Command {
   11      Get(String),
   12      Set(String, Bytes),
   13  }
   14  
   15  // Message type sent over the channel to the connection task.
   16  //
   17  // `Command` is the command to forward to the connection.
   18  //
   19  // `oneshot::Sender` is a channel type that sends a **single** value. It is used
   20  // here to send the response received from the connection back to the original
   21  // requester.
   22  type Message = (Command, oneshot::Sender<Result<Option<Bytes>>>);
   23  
   24  /// Receive commands sent through the channel and forward them to client. The
   25  /// response is returned back to the caller via a `oneshot`.
   26  async fn run(mut client: Client, mut rx: Receiver<Message>) {
   27      // Repeatedly pop messages from the channel. A return value of `None`
   28      // indicates that all `BufferedClient` handles have dropped and there will never be
   29      // another message sent on the channel.
   30      while let Some((cmd, tx)) = rx.recv().await {
   31          // The command is forwarded to the connection
   32          let response = match cmd {
   33              Command::Get(key) => client.get(&key).await,
   34              Command::Set(key, value) => client.set(&key, value).await.map(|_| None),
   35          };
   36  
   37          // Send the response back to the caller.
   38          //
   39          // Failing to send the message indicates the `rx` half dropped
   40          // before receiving the message. This is a normal runtime event.
   41          let _ = tx.send(response);
   42      }
   43  }
   44  
   45  #[derive(Clone)]
   46  pub struct BufferedClient {
   47      tx: Sender<Message>,
   48  }
   49  
   50  impl BufferedClient {
   51      /// Create a new client request buffer
   52      ///
   53      /// The `Client` performs Redis commands directly on the TCP connection. Only a
   54      /// single request may be in-flight at a given time and operations require
   55      /// mutable access to the `Client` handle. This prevents using a single Redis
   56      /// connection from multiple Tokio tasks.
   57      ///
   58      /// The strategy for dealing with this class of problem is to spawn a dedicated
   59      /// Tokio task to manage the Redis connection and using "message passing" to
   60      /// operate on the connection. Commands are pushed into a channel. The
   61      /// connection task pops commands off of the channel and applies them to the
   62      /// Redis connection. When the response is received, it is forwarded to the
   63      /// original requester.
   64      ///
   65      /// The returned `BufferedClient` handle may be cloned before passing the new handle to
   66      /// separate tasks.
   67      pub fn buffer(client: Client) -> BufferedClient {
   68          // Setting the message limit to a hard coded value of 32. in a real-app, the
   69          // buffer size should be configurable, but we don't need to do that here.
   70          let (tx, rx) = channel(32);
   71  
   72          // Spawn a task to process requests for the connection.
   73          tokio::spawn(async move { run(client, rx).await });
   74  
   75          // Return the `BufferedClient` handle.
   76          BufferedClient { tx }
   77      }
   78  
   79      /// Get the value of a key.
   80      ///
   81      /// Same as `Client::get` but requests are **buffered** until the associated
   82      /// connection has the ability to send the request.
   83      pub async fn get(&mut self, key: &str) -> Result<Option<Bytes>> {
   84          // Initialize a new `Get` command to send via the channel.
   85          let get = Command::Get(key.into());
   86  
   87          // Initialize a new oneshot to be used to receive the response back from the connection.
   88          let (tx, rx) = oneshot::channel();
   89  
   90          // Send the request
   91          self.tx.send((get, tx)).await?;
   92  
   93          // Await the response
   94          match rx.await {
   95              Ok(res) => res,
   96              Err(err) => Err(err.into()),
   97          }
   98      }
   99  
  100      /// Set `key` to hold the given `value`.
  101      ///
  102      /// Same as `Client::set` but requests are **buffered** until the associated
  103      /// connection has the ability to send the request
  104      pub async fn set(&mut self, key: &str, value: Bytes) -> Result<()> {
  105          // Initialize a new `Set` command to send via the channel.
  106          let set = Command::Set(key.into(), value);
  107  
  108          // Initialize a new oneshot to be used to receive the response back from the connection.
